import type { WikiKindRegistry } from './kind-registry.js'

export function renderWikiKindGuidance(registry: WikiKindRegistry): string {
  const lines = [
    '# Wiki kind reference (generated)',
    '',
    'Generated from `packages/core/src/wiki/kinds.json`. Do not edit this file.',
    'Run `pnpm wiki:kinds:generate` after editing the registry.',
    'Read [shared page rules](page-rules.md) for identity, evidence and migration safety.',
    'Read only the selected kind below; use `memon --project-root . show <W-id>` for an existing page and its diagnostics.',
    '',
  ]
  for (const kind of [...registry.kinds].sort((left, right) => left.order - right.order)) {
    lines.push(
      `## ${kind.id}`,
      '',
      kind.en.purpose,
      '',
      `Suitable uses: ${kind.en.uses.join('; ')}`,
      '',
      `Examples (advisory): ${kind.en.examples.join('; ')}`,
      '',
      `Distinctions: ${kind.en.distinctions}`,
      '',
      kind.en.authoring,
      '',
      `- Status vocabulary: ${kind.policy.statuses.join(' / ') || 'none'}.`,
      '- Status is optional; creation makes no research judgment.',
      '- Date is optional (YYYY-MM-DD when supplied).',
      '- Structured sources are optional; cite evidence where useful.',
      '- Body organization is free-form; no missing-section warnings or generated template.',
      '- Required H2s: none.',

      `- Related kinds: ${kind.relatedKinds.join(', ') || 'none'}.`,
      '',
    )
  }
  lines.push(
    '## Reserved directories',
    '',
    registry.reservedIds.map((id) => `\`${id}\``).join(', '),
    '',
    'These are not canonical page kinds. Any safe topic category is accepted without a kind warning.',
    'Use `memon --project-root . wiki move` for relocation or the migration Skill for conversion; registry edits never rewrite or review pages.',
    '',
  )
  return lines.join('\n')
}
